const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define city locations
  const shanghai = ee.Geometry.Point([121.4737, 31.2304]);
  const beijing = ee.Geometry.Point([116.4074, 39.9042]);

  // Function to get LST for a date range
  function getLST(startDate, endDate, geometry) {
    const collection = ee.ImageCollection('MODIS/006/MOD11A1')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .select('LST_Day_1km');

    const size = collection.size().getInfo();
    if (size === 0) {
      return null;
    }

    const meanImage = collection.mean().multiply(0.02).subtract(273.15); // Convert to Celsius

    const result = meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });

    const count = collection.count().reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    return {
      value: result.get('LST_Day_1km').getInfo(),
      count: count
    };
  }

  // Calculate baseline (2000-2012) for Aug 5-12
  let shanghaiBaseline = [];
  let beijingBaseline = [];

  for (let year = 2000; year <= 2012; year++) {
    const start = `${year}-08-05`;
    const end = `${year}-08-13`;

    const shResult = getLST(start, end, shanghai);
    const bjResult = getLST(start, end, beijing);

    if (shResult && shResult.value !== null) {
      shanghaiBaseline.push(shResult.value);
    }
    if (bjResult && bjResult.value !== null) {
      beijingBaseline.push(bjResult.value);
    }
  }

  if (shanghaiBaseline.length === 0 || beijingBaseline.length === 0) {
    console.log("Insufficient baseline data");
    console.log("<answer>C1</answer>");
    return;
  }

  const shBaselineMean = shanghaiBaseline.reduce((a, b) => a + b) / shanghaiBaseline.length;
  const bjBaselineMean = beijingBaseline.reduce((a, b) => a + b) / beijingBaseline.length;

  console.log(`Shanghai baseline (2000-2012): ${shBaselineMean.toFixed(2)}°C (n=${shanghaiBaseline.length})`);
  console.log(`Beijing baseline (2000-2012): ${bjBaselineMean.toFixed(2)}°C (n=${beijingBaseline.length})`);

  // Calculate 2013 values
  const sh2013 = getLST('2013-08-05', '2013-08-13', shanghai);
  const bj2013 = getLST('2013-08-05', '2013-08-13', beijing);

  if (!sh2013 || !bj2013) {
    console.log("No data for 2013 period");
    console.log("<answer>C1</answer>");
    return;
  }

  if (sh2013.value === null || bj2013.value === null) {
    console.log("Invalid 2013 values");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Shanghai 2013: ${sh2013.value.toFixed(2)}°C (count=${sh2013.count.toFixed(1)})`);
  console.log(`Beijing 2013: ${bj2013.value.toFixed(2)}°C (count=${bj2013.count.toFixed(1)})`);

  // Calculate anomalies
  const shAnomaly = sh2013.value - shBaselineMean;
  const bjAnomaly = bj2013.value - bjBaselineMean;

  console.log(`Shanghai anomaly: ${shAnomaly.toFixed(2)}°C`);
  console.log(`Beijing anomaly: ${bjAnomaly.toFixed(2)}°C`);

  // Validation check
  if (isNaN(shAnomaly) || isNaN(bjAnomaly) || Math.abs(shAnomaly) > 50 || Math.abs(bjAnomaly) > 50) {
    console.log("Invalid anomaly values");
    console.log("<answer>C3</answer>");
    return;
  }

  if (shAnomaly > bjAnomaly) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
